-- ------------------------------------------------------------
-- Verification
-- ------------------------------------------------------------
select p.name, p.program_type, count(r.id) as rule_count
from programs p left join program_eligibility_rules r on r.program_id = p.id
where p.administering_entity = 'Ohio Housing Finance Agency'
group by p.name, p.program_type order by p.name;

select glt.table_name, count(*) as row_count from geo_lookup_values glv
join geo_lookup_tables glt on glt.id = glv.lookup_table_id
where glt.table_name like 'oh_ohfa%' group by glt.table_name order by glt.table_name;