insert into states (state_code, state_name, is_active) values ('OH', 'Ohio', true) on conflict (state_code) do nothing;
insert into geo_lookup_tables (id, table_name, description, value_type)
values
  ('743963e7-de9b-4ab2-ac1e-f3c0406deada', 'oh_ohfa_income_limits', 'OHFA non-target income limits, all 88 counties, 2 household-size tiers (household_size=2 for 1-2 person, household_size=3 for 3+ person). Also used as the base for Grants for Grads/Next Home/FTHB Edge via the TARGET table below (see note on that program). Source: OHFA Income/Purchase Price Limits PDF, eff. 7/1/26.', 'income_limit'),
  ('7bc2d574-17ed-44af-823d-fe5d81648307', 'oh_ohfa_income_limits_targeted', 'OHFA target-area income limits, all 88 counties. NOTE: unlike IHCDA/KHC, Ohio does not publish a static list of which tracts are targeted -- targeting is determined via a live ArcGIS lookup tool (ohiohome.org/Geodata). This table lets the app show the correct ELEVATED figure IF a buyer is in a targeted tract, but cannot determine targeted status itself -- targetedTractCaveat() will always return needsVerification for OH, permanently (not an interim state pending future data, per 8/14/26 scope decision).', 'income_limit'),
  ('93519dfc-b625-47e5-abf5-5268ef00367b', 'oh_ohfa_purchase_price_limits', 'OHFA non-target purchase price limits (1-family), all 88 counties. Structurally MSA-grouped in the source PDF (Columbus MSA vs. every other MSA/county, which all share identical figures) -- expanded here to per-county rows to fit the schema''s county_fips-keyed lookup pattern. Source: same PDF as income limits.', 'purchase_price_cap'),
  ('cc77e206-ab4c-4569-a93c-360ad7e7785b', 'oh_ohfa_purchase_price_limits_targeted', 'OHFA target-area purchase price limits (1-family), all 88 counties. Same targeted-status caveat as oh_ohfa_income_limits_targeted -- no static tract list exists to determine which specific buyers this applies to.', 'purchase_price_cap')
insert into geo_lookup_values (lookup_table_id, state_code, county_fips, household_size, numeric_value, effective_date, source_url)
