insert into programs (id, name, administering_entity, program_type, description, source_url, funding_status, last_verified_date) values (
insert into program_eligibility_rules (id, program_id, rule_type, rule_config, evaluation_order) values
  ('6521fcd9-398d-48fe-9250-45ef5958bc8a', 'd3a98cfb-5bca-4060-ab6d-1878f36e18e9', 'geographic_scope', '{"scope_level": "state", "allowed_values": ["OH"]}', 0),
  ('5dcc50c8-6dbe-47c2-8c55-9fa2e0454191', 'd3a98cfb-5bca-4060-ab6d-1878f36e18e9', 'income_threshold', '{"comparator": "lte", "income_basis": "household", "geo_scope": "county", "lookup_table": "oh_ohfa_income_limits", "targeted_lookup_table": "oh_ohfa_income_limits_targeted", "targeted_tract_source_url": "https://ohiohome.org/Geodata/default", "targeted_tract_data_status": "needsVerification", "note": "OH has no static targeted-tract list (live ArcGIS tool only) -- unlike other states, this caveat is a PERMANENT end state per 8/14/26 scope decision, not interim pending future extraction. Given OHFA''s own FAQ states most counties contain both target and non-target areas, expect this caveat to fire broadly -- that is accurate, not a bug."}', 1),
  ('5492afe5-6037-4449-acb3-a8b6c51158e7', 'd3a98cfb-5bca-4060-ab6d-1878f36e18e9', 'financial_underwriting', '{"field": "purchase_price_cap", "comparator": "lte", "geo_scope": "county", "lookup_table": "oh_ohfa_purchase_price_limits", "targeted_lookup_table": "oh_ohfa_purchase_price_limits_targeted", "targeted_tract_source_url": "https://ohiohome.org/Geodata/default", "note": "Same permanent targeted-caveat as income_threshold above."}', 2),
  ('30fded6a-0c12-40a6-8c3a-e7d5f12e958c', 'd3a98cfb-5bca-4060-ab6d-1878f36e18e9', 'financial_underwriting', '{"field": "credit_score", "comparator": "gte", "value": 640, "note": "640 is the Conventional/USDA/VA floor; FHA requires 650. Using the lower (more permissive) figure statewide rather than guessing which loan type a given buyer will use -- same approach as KY DPA''s analogous multi-product ambiguity."}', 3);
insert into programs (id, name, administering_entity, program_type, description, source_url, funding_status, last_verified_date) values (
insert into program_eligibility_rules (id, program_id, rule_type, rule_config, evaluation_order) values
  ('b45c3856-6958-4b67-a7ba-53b2b4cac543', 'c9a2b5a0-3fdf-4d05-9595-a9967e834f98', 'geographic_scope', '{"scope_level": "state", "allowed_values": ["OH"]}', 0),
  ('bddec800-6fd9-478e-8ac8-dfb5f895049a', 'c9a2b5a0-3fdf-4d05-9595-a9967e834f98', 'occupation_membership', '{"allowed_tags": ["veteran", "active_duty_military", "reserve_military", "police_officer", "firefighter", "volunteer_firefighter", "emt", "paramedic", "physician", "nurse_practitioner", "registered_nurse", "licensed_practical_nurse", "stna", "teacher_prek12", "school_administrator", "school_counselor"], "match_mode": "any_of", "note": "Placeholder tags based directly on OHFA''s published category language -- NOT verified against the live occupation_taxonomy table''s actual tag values. Must be cross-checked/reconciled with existing taxonomy entries (e.g. whatever FL Hometown Heroes already uses for overlapping categories) before this rule will correctly match real buyer profiles."}', 1),
  ('b25dae2e-25f1-4f5c-a826-adc515f425c7', 'c9a2b5a0-3fdf-4d05-9595-a9967e834f98', 'income_threshold', '{"comparator": "lte", "income_basis": "household", "geo_scope": "county", "lookup_table": "oh_ohfa_income_limits", "targeted_lookup_table": "oh_ohfa_income_limits_targeted", "targeted_tract_source_url": "https://ohiohome.org/Geodata/default", "targeted_tract_data_status": "needsVerification"}', 2),
  ('cc8cc658-d66a-4657-86a9-d4505e1a45c3', 'c9a2b5a0-3fdf-4d05-9595-a9967e834f98', 'financial_underwriting', '{"field": "purchase_price_cap", "comparator": "lte", "geo_scope": "county", "lookup_table": "oh_ohfa_purchase_price_limits", "targeted_lookup_table": "oh_ohfa_purchase_price_limits_targeted", "targeted_tract_source_url": "https://ohiohome.org/Geodata/default"}', 3),
  ('f584654b-6d6a-4f14-b8cb-1ad83bb134d1', 'c9a2b5a0-3fdf-4d05-9595-a9967e834f98', 'financial_underwriting', '{"field": "credit_score", "comparator": "gte", "value": 640, "note": "Same 640/650 loan-type nuance as DPA."}', 4);
