  ('46eb9062-c25c-4b35-a6d2-e58cac10bf53', '63d093af-5ad8-4fdd-ab83-7dc5de22270c', 'geographic_scope', '{"scope_level": "state", "allowed_values": ["OH"]}', 0),
  ('42d9d06d-97c8-4971-9388-dc54a7e863b3', '63d093af-5ad8-4fdd-ab83-7dc5de22270c', 'buyer_status', '{"status_required": "first_time_buyer", "lookback_years": 3, "note": "MTC''s own eligibility page lists this requirement without restating the veteran/target-area exemptions that OHFA''s base Homebuyer Program explicitly offers -- unconfirmed whether those exemptions extend to MTC. Curated as a strict FTB requirement; flagged rather than assumed."}', 1),
  ('d226d1ad-65a6-495b-9d7b-86c8ea8950ba', '63d093af-5ad8-4fdd-ab83-7dc5de22270c', 'income_threshold', '{"comparator": "lte", "income_basis": "household", "geo_scope": "county", "lookup_table": "oh_ohfa_income_limits", "targeted_lookup_table": "oh_ohfa_income_limits_targeted", "targeted_tract_source_url": "https://ohiohome.org/Geodata/default", "targeted_tract_data_status": "needsVerification"}', 2),
  ('2f7a739a-790e-491b-8c89-5da2e4973951', '63d093af-5ad8-4fdd-ab83-7dc5de22270c', 'financial_underwriting', '{"field": "purchase_price_cap", "comparator": "lte", "geo_scope": "county", "lookup_table": "oh_ohfa_purchase_price_limits", "targeted_lookup_table": "oh_ohfa_purchase_price_limits_targeted", "targeted_tract_source_url": "https://ohiohome.org/Geodata/default"}', 3),
  ('e5317582-3610-47e6-826a-c08dfe3d2527', '63d093af-5ad8-4fdd-ab83-7dc5de22270c', 'financial_underwriting', '{"field": "credit_score", "comparator": "gte", "value": 640, "note": "MTC Plus requires OHFA loan credit standards, same 640/650 nuance."}', 4);
